/*
 * Resolved design tokens (raw values) for renderers that cannot read CSS
 * custom properties, such as the canvas chart layer and, from M2, the canvas
 * grid. DOM components use `@glassgrid/ui/tokens.css` instead.
 *
 * The JSON files are generated by tokens/build-tokens.js; do not edit them.
 */
import dark from '../tokens/glassgrid.resolved.dark.json';
import light from '../tokens/glassgrid.resolved.light.json';

export type ThemeName = 'light' | 'dark';

/** Shape of one resolved theme (both themes share it). */
export type ResolvedTokens = Omit<typeof light, 'theme'> & { readonly theme: ThemeName };

const lightTokens: ResolvedTokens = { ...light, theme: 'light' };
// Assigning to the light shape makes the build fail if the themes ever diverge.
const darkTokens: ResolvedTokens = { ...dark, theme: 'dark' };

export const resolvedTokens: Readonly<Record<ThemeName, ResolvedTokens>> = Object.freeze({
  light: lightTokens,
  dark: darkTokens,
});

export function tokensFor(theme: ThemeName): ResolvedTokens {
  return resolvedTokens[theme];
}

export default resolvedTokens;
